```python
# Define a function to determine whether a number is prime
def is_prime(n):
    # A prime number must be greater than or equal to 2
    if n < 2:
        return False
    # Iterate from 2 to the square root of n, checking whether n is divisible by any of these numbers
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            return False
    return True

# Iterate through all numbers from 1 to 100, using the is_prime function to determine whether each is prime
for i in range(1, 101):
    if is_prime(i):
        print(i)
```

